        "Per poche brevi settimane, le pianure attorno a Ndutu ospitano una delle più alte concentrazioni di giovane fauna vulnerabile di tutto il pianeta — e ogni predatore nel raggio di chilometri sa esattamente dove trovarsi. Questa tensione plasma tutto il modo in cui questi giorni vengono fotografati. I veicoli mantengono la posizione anziché spostarsi rapidamente, perché la storia qui spesso richiede tempo per svolgersi: una madre gnu che gira attorno a un cucciolo appena nato che non ha ancora trovato le zampe, un ghepardo che legge la mandria da un termitaio, uno sciacallo che aspetta il suo momento ai margini. La vostra guida non si limita a trovare la fauna selvatica — legge la tensione che si accumula sulle pianure e vi aiuta a essere in posizione prima che esploda.",
