      "Aggiornato per la stagione 2027. Dodici giorni, due tipi di straordinario completamente diversi. La prima metà è il Rwanda nella sua forma più vivida — scimpanzé che si muovono tra la volta della foresta a Nyungwe, gorilla di montagna sui pendii avvolti nella nebbia sopra Musanze, cercopitechi dorati che sfrecciano tra il bambù, e una gita in barca sul Lago Kivu tra una tappa e l'altra. La seconda metà non chiede nulla: quattro notti senza fretta sulla sabbia bianca di Zanzibar, con una mattinata a Stone Town inclusa per chi desidera un'altra storia da raccontare prima che il relax prenda davvero il sopravvento.",
      "È una struttura che funziona particolarmente bene per tre tipi di viaggiatori. Per i viaggiatori anziani, è l'itinerario stesso a stabilire il ritmo — vere permanenze di due notti invece di una serie di soste di una sola notte, e una seconda metà autenticamente riposante inclusa fin dall'inizio, non trattata come un ripensamento. Per le coppie che festeggiano un anniversario, il contrasto è tutto il senso del viaggio: giorni che chiedono qualcosa insieme in Rwanda, seguiti da giorni che non chiedono nulla a Zanzibar. E per i gruppi — amici, famiglia allargata, viaggi multi-generazionali — la struttura dà a ognuno lo spazio per vivere la metà avventura al proprio ritmo, prima di ritrovarsi tutti insieme in spiaggia.",
